package hotel.reservations;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import hotel.rooms.Room;
import hotel.rooms.Rooms;
import java.math.BigDecimal;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

class PriceCalculatorTest {

    private final PriceCalculator calculator = new PriceCalculator();
    private final Room standardRoom = new Rooms().find(101).orElseThrow();
    private final Room deluxe = new Rooms().find(201).orElseThrow();
    private final Room suite = new Rooms().find(301).orElseThrow();

    private Price price(Room room, String checkIn, String checkOut, RatePlan ratePlan) {
        return price(room, checkIn, checkOut, ratePlan, null);
    }

    private Price price(Room room, String checkIn, String checkOut, RatePlan ratePlan, String companyCode) {
        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
        return calculator.calculate(room, new NewReservation(
                room.number(), guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 1, ratePlan, companyCode));
    }

    @Test
    void lowSeasonNightsCostTheNightlyRate() {
        Price price = price(standardRoom, "2027-03-10", "2027-03-13", RatePlan.STANDARD);

        assertEquals(3, price.nights());
        assertEquals(new BigDecimal("749.70"), price.subtotal());
        assertEquals(new BigDecimal("0.00"), price.discount());
        assertEquals(new BigDecimal("749.70"), price.total());
    }

    @Test
    void highSeasonStartsOnDecember15() {
        Price price = price(standardRoom, "2027-12-14", "2027-12-16", RatePlan.STANDARD);

        // December 14: 249.90; December 15: 249.90 + 20% = 299.88
        assertEquals(new BigDecimal("549.78"), price.total());
    }

    @Test
    void highSeasonEndsWithFebruary() {
        Price price = price(standardRoom, "2028-02-29", "2028-03-02", RatePlan.STANDARD);

        // February 29 (leap year): 299.88; March 1: 249.90
        assertEquals(new BigDecimal("549.78"), price.total());
    }

    @Test
    void julyIsHighSeason() {
        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 6, 30)));
        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 7, 1)));
        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 7, 31)));
        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 8, 1)));
    }

    @Test
    void nonRefundableTakes15PercentOffRoundingHalfEven() {
        Price price = price(standardRoom, "2027-03-10", "2027-03-11", RatePlan.NON_REFUNDABLE);

        // 15% of 249.90 = 37.485, which rounds half-even to 37.48 (half-up would give 37.49)
        assertEquals(new BigDecimal("37.48"), price.discount());
        assertEquals(new BigDecimal("212.42"), price.total());
    }

    @Test
    void nonRefundableDiscountIsOnTheHighSeasonPrice() {
        Price price = price(suite, "2027-01-05", "2027-01-09", RatePlan.NON_REFUNDABLE);

        // 4 nights of 579.90 + 20% = 695.88 each
        assertEquals(new BigDecimal("2783.52"), price.subtotal());
        assertEquals(new BigDecimal("417.53"), price.discount());
        assertEquals(new BigDecimal("2365.99"), price.total());
    }

    @Test
    void corporateGivesTheCompanysDiscount() {
        Price tecnosul = price(deluxe, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "TECNOSUL");

        assertEquals(new BigDecimal("779.80"), tecnosul.subtotal());
        assertEquals(new BigDecimal("93.58"), tecnosul.discount());
        assertEquals(new BigDecimal("686.22"), tecnosul.total());
        assertEquals(new BigDecimal("0.18"), price(deluxe, "2027-03-10", "2027-03-12", RatePlan.CORPORATE,
                "AGROVALE").discount().divide(new BigDecimal("779.80"), 2, java.math.RoundingMode.HALF_EVEN));
        assertEquals(new BigDecimal("194.95"), price(deluxe, "2027-03-10", "2027-03-12", RatePlan.CORPORATE,
                "FARMAVIDA").discount());
    }

    @Test
    void weekendPackageCostsTheFixedPriceOfTheRoomTypeInAnySeason() {
        Price inMarch = price(deluxe, "2027-03-12", "2027-03-14", RatePlan.WEEKEND_PACKAGE);
        Price inJuly = price(suite, "2027-07-02", "2027-07-04", RatePlan.WEEKEND_PACKAGE);

        assertEquals(2, inMarch.nights());
        assertEquals(new BigDecimal("820.00"), inMarch.subtotal());
        assertEquals(new BigDecimal("0.00"), inMarch.discount());
        assertEquals(new BigDecimal("820.00"), inMarch.total());
        assertEquals(new BigDecimal("1200.00"), inJuly.total());
    }

    @Test
    void longStayTakes10PercentOffAndKeepsTheHighSeasonSurcharge() {
        Price march = price(standardRoom, "2027-03-01", "2027-03-08", RatePlan.LONG_STAY);
        Price july = price(standardRoom, "2027-07-25", "2027-08-01", RatePlan.LONG_STAY);

        assertEquals(new BigDecimal("1749.30"), march.subtotal());
        assertEquals(new BigDecimal("174.93"), march.discount());
        assertEquals(new BigDecimal("1574.37"), march.total());

        // 7 nights of 299.88 (July is high season): 2099.16, 10% = 209.916 rounds to 209.92
        assertEquals(new BigDecimal("2099.16"), july.subtotal());
        assertEquals(new BigDecimal("209.92"), july.discount());
    }
}

