    @Test
    void corporateNeedsTheCodeOfAKnownCompany() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "XPTO"))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "tecnosul"))));
    }

    @Test
    void corporateRefundsEverythingWhenCancelled() {
        Reservation reservation = service.create(
                stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "TECNOSUL"));
        service.confirm(reservation.id());

        assertEquals(new BigDecimal("686.22"), service.cancel(reservation.id()).refund());
    }

    @Test
    void theWeekendPackageIsTwoNightsFromFridayToSunday() {
        // 2027-03-10 is a Wednesday; 2027-03-12 is a Friday
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));
    }

    @Test
    void cancellingTheWeekendPackageGivesHalfBack() {
        Reservation reservation = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
        service.confirm(reservation.id());

        assertEquals(new BigDecimal("820.00"), reservation.price().total());
        assertEquals(new BigDecimal("410.00"), service.cancel(reservation.id()).refund());
    }

    @Test
    void theLongStayNeedsSevenNights() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-01", "2027-03-07", 2, RatePlan.LONG_STAY))));

        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
        service.confirm(reservation.id());

        assertEquals(new BigDecimal("1574.37"), reservation.price().total());
        assertEquals(new BigDecimal("1574.37"), service.cancel(reservation.id()).refund());
    }

    @Test
    void otherPlansIgnoreTheCompanyCode() {
        Reservation reservation = service.create(
                stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD, "XPTO"));

        assertEquals(new BigDecimal("249.90"), reservation.price().total());
    }
}

